package com.studyhub.controller;
import com.studyhub.model.*; import com.studyhub.repository.*; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api") public class PaymentController { private final UserAccountRepository users; private final SubscriptionRepository subscriptions; private final DemoPaymentRepository payments; private static final Map<String,Long> PRICES=Map.of("plus",199000L,"pro",299000L); public PaymentController(UserAccountRepository u,SubscriptionRepository s,DemoPaymentRepository p){users=u;subscriptions=s;payments=p;}
 @GetMapping("/subscription") public ResponseEntity<?> get(@RequestParam Long userId){return ResponseEntity.ok(subscriptions.findByUserId(userId).map(this::view).orElse(Map.of("plan","free","status","active")));}
 @PostMapping("/payment/demo") public ResponseEntity<?> pay(@RequestBody Map<String,Object> b){Long userId=Long.valueOf(String.valueOf(b.get("userId")));String plan=String.valueOf(b.get("plan")).toLowerCase();if(!users.existsById(userId))return ResponseEntity.status(404).body(Map.of("error","Không tìm thấy tài khoản."));if(!PRICES.containsKey(plan))return ResponseEntity.badRequest().body(Map.of("error","Gói thanh toán không hợp lệ.")); DemoPayment p=new DemoPayment();p.setUserId(userId);p.setPlan(plan);p.setAmount(PRICES.get(plan));p.setStatus("PENDING");p.setTransactionCode("DEMO-"+LocalDate.now().toString().replace("-","")+"-"+UUID.randomUUID().toString().substring(0,5).toUpperCase());payments.save(p); try{Thread.sleep(1200);}catch(InterruptedException e){Thread.currentThread().interrupt();return ResponseEntity.internalServerError().body(Map.of("error","Demo payment interrupted."));}p.setStatus("SUCCESS");payments.save(p);Subscription s=subscriptions.findByUserId(userId).orElseGet(Subscription::new);s.setUserId(userId);s.setPlan(plan);s.setStatus("active");subscriptions.save(s);return ResponseEntity.ok(Map.of("transaction_code",p.getTransactionCode(),"status",p.getStatus(),"subscription",view(s)));}
 private Map<String,String> view(Subscription s){return Map.of("plan",s.getPlan(),"status",s.getStatus());}}
